def is_golomb_ruler(marks):
    distances = []
    for i in range(len(marks)):
        for j in range(i+1, len(marks)):
            distances.append(marks[j] - marks[i])
    return len(distances) == len(set(distances))

# Test the candidate [0, 1, 4, 9, 11]
marks = [0, 1, 4, 9, 11]
print(f"Is {marks} a Golomb ruler? {is_golomb_ruler(marks)}")

# Print all distances
distances = []
for i in range(len(marks)):
    for j in range(i+1, len(marks)):
        distances.append(marks[j] - marks[i])
print(f"Distances: {sorted(distances)}")
print(f"Number of distances: {len(distances)}")
print(f"Number of unique distances: {len(set(distances))}")
